function makeSeo(p){var loc=[p.city,p.country].filter(Boolean).join(', '),offer=offerPhrase(p),brand=state.settings.brand||'PropertyPilot';var title=(p.beds+'-Bedroom '+p.type+' '+offer+' in '+p.city+' | '+brand).slice(0,60);var meta=('Explore this '+p.beds+'-bedroom '+p.type+' '+offer+' in '+loc+'. '+p.area+' m², '+money(p.price,p.currency)+', '+p.condition+' condition. '+state.settings.cta+'.').slice(0,160);return {kind:'AI Draft',text:'SEO Title: '+title+'\nMeta Description: '+meta+'\nKeywords: '+[p.type,p.city,p.country,p.beds+' bedroom property',offer.toLowerCase(),'real estate'].filter(Boolean).join(', '),title:title,meta:meta,history:[]}}
function makeSocial(p){var loc=[p.city,p.country].filter(Boolean).join(', '),offer=offerPhrase(p),headline=p.beds+' Beds. '+p.type+'. '+loc+'.';var intro=p.listingPurpose==='For Rent'?'Available to rent: ':p.listingPurpose==='Short Stay'?'Available for short stays: ':p.listingPurpose==='Commercial Lease'?'Available for commercial lease: ':'New on the market: ';var primary=intro+'a '+p.beds+'-bedroom '+p.type.toLowerCase()+' with '+p.baths+' bathrooms and approximately '+p.area+' m² in '+loc+'. '+offer+': '+money(p.price,p.currency)+'. '+p.features.slice(0,3).join(' • ')+'. '+state.settings.cta+'.';return {facebook:{kind:'AI Draft',headline:headline,primaryText:primary,cta:state.settings.cta,short:headline+' '+money(p.price,p.currency)+'. '+state.settings.cta+'.',history:[]},instagram:{kind:'AI Draft',hook:p.beds+' bedrooms. One strong next move.',text:headline+'\n\n'+p.features.join(' • ')+'\n\n'+offer+': '+money(p.price,p.currency)+' · '+state.settings.cta+'.',cta:state.settings.cta,hashtags:['#'+p.type.replace(/\s/g,''),'#'+p.city.replace(/\s/g,''),'#RealEstate','#PropertyForSale'],history:[]},social:{kind:'AI Draft',text:p.beds+' bed '+p.type+' · '+loc+' · '+money(p.price,p.currency)+'\n'+p.features.slice(0,4).map(function(f){return '• '+f}).join('\n')+'\n'+offer+'. '+state.settings.cta+'.',history:[]}}}
function makeEmail(p){var loc=[p.city,p.country].filter(Boolean).join(', '),offer=offerPhrase(p);return {kind:'AI Draft',subject:offer+' — '+p.beds+'-bedroom '+p.type.toLowerCase()+' in '+loc,text:'Hi there,\n\nI’m sharing a '+p.beds+'-bedroom '+p.type.toLowerCase()+' in '+loc+'.\n\nListing purpose: '+offer+'. Price / asking amount: '+money(p.price,p.currency)+'. The property offers approximately '+p.area+' m², '+p.baths+' bathrooms and '+p.condition.toLowerCase()+' condition.\n\nKey benefits:\n'+p.features.map(function(f){return '• '+f}).join('\n')+'\n\n'+state.settings.cta+'.\n\nBest,\n'+state.settings.agent+'\n'+state.settings.contact,history:[]}}
function generate(p){var loc=[p.city,p.country].filter(Boolean).join(', '),offer=offerPhrase(p),tid=p.template||state.template;var leads={luxury:'A refined ',residential:'A practical ',rental:'A rental-ready ',commercial:'A commercially focused ',development:'A new-development ',vacation:'A lifestyle-led ',investor:'An investment-focused '};var lead=leads[tid]||'A well-presented ';if(state.settings.tone==='Luxury')lead='A premium ';else if(state.settings.tone==='Friendly')lead='A welcoming ';else if(state.settings.tone==='Minimal')lead='A concise ';else if(state.settings.tone==='Persuasive')lead='A compelling ';var prefix=tid==='luxury'?'Elegant ':tid==='vacation'?'Escape-ready ':tid==='investor'?'Investment-focused ':'';var title=prefix+p.beds+'-Bedroom '+p.type+' in '+p.city+(p.features.indexOf('Waterfront views')>=0?' with Waterfront Views':'');var focus=tid==='rental'?'tenant-friendly practical details':tid==='commercial'?'commercial use and operational clarity':tid==='development'?'new-development positioning':tid==='vacation'?'lifestyle and stay features':tid==='investor'?'clear factual details for investment review':tid==='luxury'?'refined presentation and distinctive features':'space, location and practical features';var desc=lead+p.type.toLowerCase()+' '+offer.toLowerCase()+' in '+loc+', with a focus on the supplied property facts and '+focus+'.\n\nThe property provides approximately '+p.area+' m² of floor area with '+p.beds+' bedrooms and '+p.baths+' bathrooms. '+p.condition+' condition, '+p.furnished.toLowerCase()+' presentation and '+p.parking.toLowerCase()+' parking are part of the supplied property facts.\n\nHighlights include '+p.features.join(', ')+'. This copy intentionally avoids unsupported claims about schools, commute times, investment returns or amenities.\n\n'+(p.notes||'')+'\n\n'+state.settings.cta+'. Contact '+state.settings.agent+' at '+state.settings.contact+' for further information.';var social=makeSocial(p);return {title:{kind:'AI Draft',text:title},description:{kind:'AI Draft',text:desc},seo:makeSeo(p),facebook:social.facebook,instagram:social.instagram,short:{kind:'AI Draft',text:p.beds+' bed / '+p.baths+' bath '+p.type+' in '+loc+'. '+p.area+' m², '+money(p.price,p.currency)+'. '+p.features.slice(0,3).join(' • ')+'. '+offer+'. '+state.settings.cta+'.'},email:makeEmail(p),social:social.social,highlights:{kind:'AI Draft',text:p.features.map(function(f){return '• '+f}).join('\n')}}}
