function properties(){var ps=state.properties.filter(function(p){var q=query.toLowerCase();var hit=!q||[p.title,p.city,p.country,p.type].join(' ').toLowerCase().indexOf(q)>=0;return hit&&(filter==='all'||p.status===filter)});return shell('properties',head('Portfolio','Properties','Manage property records, content packages and publication state.','<button class="primary-btn" onclick="go(\'new\')">+ Create Property</button>')+'<div class="toolbar"><div class="searchbox">⌕<input value="'+esc(query)+'" placeholder="Search properties, locations or types" oninput="setQuery(this.value)"></div><select onchange="setFilter(this.value)"><option value="all">All statuses</option>'+['Draft','Generating','Ready','Published','Archived'].map(function(s){return '<option '+(filter===s?'selected':'')+'>'+s+'</option>'}).join('')+'</select></div><div class="panel"><div class="table-wrap"><table><thead><tr><th>Property</th><th>Location</th><th>Type</th><th>Price</th><th>Bedrooms</th><th>Status</th><th>Content</th><th>Created</th><th></th></tr></thead><tbody>'+ps.map(function(p){return '<tr><td><div class="property-cell"><img src="'+esc(p.images[p.primary||0]||IMG[0])+'"><div><b>'+esc(p.title)+'</b><span>'+esc(p.address)+'</span></div></div></td><td>'+esc(p.city)+', '+esc(p.country)+'</td><td>'+esc(p.type)+'</td><td>'+money(p.price,p.currency)+'</td><td>'+p.beds+'</td><td>'+badge(p.status)+'</td><td>'+contentCount(p)+'/8</td><td>'+date(p.createdAt)+'</td><td><button class="small-btn" onclick="go(\'property/'+p.id+'\')">Open</button></td></tr>'}).join('')+'</tbody></table></div></div>')}
